try {
  const CP = Java.use('okhttp3.CertificatePinner');
  if (CP.check) {
    CP.check.overloads.forEach(function (ov) {
      ov.implementation = function () {
        log('okhttp3.CertificatePinner.check bypass argc=' + arguments.length);
        return;
      };
    });
    log('hooked okhttp3.CertificatePinner.check');
  }
} catch (e) { log('CertificatePinner hook skipped: ' + e); }

try {
  const TM = Java.use('com.android.org.conscrypt.TrustManagerImpl');
  if (TM.checkTrustedRecursive) {
    TM.checkTrustedRecursive.overloads.forEach(function (ov) {
      ov.implementation = function () {
        log('TrustManagerImpl.checkTrustedRecursive bypass');
        return Java.use('java.util.ArrayList').$new();
      };
    });
    log('hooked TrustManagerImpl.checkTrustedRecursive');
  }
  if (TM.verifyChain) {
    TM.verifyChain.overloads.forEach(function (ov) {
      ov.implementation = function () {
        log('TrustManagerImpl.verifyChain bypass');
        return arguments[0];
      };
    });
    log('hooked TrustManagerImpl.verifyChain');
  }
} catch (e) { log('TrustManagerImpl hook skipped: ' + e); }

try {
  const HV = Java.use('javax.net.ssl.HostnameVerifier');
  log('HostnameVerifier is an interface; hook concrete verifier classes if needed.');
} catch (e) { }
